const rows = $input.all();
const cfg = {};
for (const it of rows) {
  const k = it.json.setting !== undefined ? it.json.setting : it.json.key;
  if (k === undefined || k === null || String(k).trim() === '') continue;
  cfg[String(k).trim()] = it.json.value;
}
return [{ json: cfg }];

// Picks the next QUEUED rows in priority order and assigns each to a mailbox.
// Per-mailbox daily caps. Each investor belongs to exactly one mailbox (stable hash),
// so the senders never collide and no row can be sent twice.
const cfg = $('Build CONFIG object').first().json;
const today = new Date().toLocaleString('sv-SE', { timeZone: 'Asia/Kolkata' }).slice(0, 10);
const todaySerial = Math.floor((Date.UTC(+today.slice(0,4), +today.slice(5,7) - 1, +today.slice(8,10)) - Date.UTC(1899, 11, 30)) / 86400000);
const isToday = v => {
  const s = String(v == null ? '' : v).trim();
  if (!s) return false;
  if (s.startsWith(today)) return true;
  const n = Number(s);
  return Number.isFinite(n) && Math.floor(n) === todaySerial;
};
const numCfg = (k, d) => { const v = Number(cfg[k]); return Number.isFinite(v) && v > 0 ? v : d; };

// name = the human the recipient sees in the signature. The body's opening line
// is rewritten to match, so "I am X from Sidana Ventures" never contradicts the
// signature block underneath it. (User instruction, 30 Sep 2026.)
const MAILBOXES = [
  { id: 'mb5', addr: 'shradhaa@sidanaventures.com',  name: 'Shradhaa', cap: numCfg('ONBOARDING_CAP_MB5', 10), sig: 'Get Shradhaa signature' },
  { id: 'mb4', addr: 'akansha@sidanaventures.com',   name: 'Akansha',  cap: numCfg('ONBOARDING_CAP_MB4', 10), sig: 'Get mb4 signature' },
  { id: 'mb3', addr: 'investors@sidanaventures.com', name: 'Aditya',   cap: numCfg('ONBOARDING_CAP_MB3', 10), sig: 'Get mb3 signature' },
  { id: 'mb2', addr: 'dealflow@sidanaventures.com',  name: 'Chaman',   cap: numCfg('ONBOARDING_CAP_MB2', 10), sig: 'Get mb2 signature' },
  { id: 'mb6', addr: 'admin@sidanaventures.com',     name: 'Bhawna',   cap: numCfg('ONBOARDING_CAP_MB6', 30), sig: 'Get mb6 signature' }
];

// Gate on the company URL, not a job title - admin@ signs as "Founder's Relations".
const SIG_MARK = 'sidanaventures.com';
const disabled = [];
for (const m of MAILBOXES) {
  let sig = '';
  try {
    const sendAs = ($(m.sig).first().json.sendAs) || [];
    const me = sendAs.find(s => String(s.sendAsEmail || '').toLowerCase() === m.addr)
            || sendAs.find(s => s.isDefault) || {};
    sig = String(me.signature || '');
  } catch (e) { sig = ''; }
  m.signature = sig;
  m.ok = sig.toLowerCase().includes(SIG_MARK);
  if (!m.ok) disabled.push(m.id + ' (' + m.addr + ': no usable signature)');
}
const ACTIVE = MAILBOXES.filter(m => m.ok);
if (!ACTIVE.length) throw new Error('No mailbox has a usable Gmail signature - aborting run, nothing sent');

const TOTAL = ACTIVE.reduce((a, m) => a + m.cap, 0);
let acc = 0;
for (const m of ACTIVE) { m.lo = acc; m.hi = acc + m.cap; acc += m.cap; }
const slotOf = s => { let h = 2166136261; const t = String(s || '').toLowerCase();
  for (let i = 0; i < t.length; i++) { h ^= t.charCodeAt(i); h = Math.imul(h, 16777619); }
  return Math.abs(h) % TOTAL; };
const mbFor = email => { const s = slotOf(email); return ACTIVE.find(m => s >= m.lo && s < m.hi) || null; };

function finalise(html, SIG, NAME) {
  let h = String(html || '');
  // The stored body is written in Shradhaa's voice. Rewrite the opening to the
  // person whose signature will actually appear, or the reader sees one name in
  // the text and a different one signed underneath.
  h = h.replace(/I am Shradhaa\b/g, 'I am ' + NAME);
  if (!h.includes('rakeshsidana.org">rakeshsidana.org</a> ') && !h.includes('LinkedIn</a> | ')) {
    h = h.replace('LinkedIn</a>)', 'LinkedIn</a> | <a href="https://rakeshsidana.org">rakeshsidana.org</a>)');
  }
  if (!h.includes('mail-sig')) {
    h = h.replace(/<p>Best,<br>[A-Za-z' ]+<br>[\s\S]*?<\/p>\s*$/, '');
    h = h + '<br><div>-- </div>' + SIG;
  }
  return h;
}

const onb = $('Read ONBOARDING').all().map(i => i.json);
const inv = $('Read INVESTORS').all().map(i => i.json);

// ---- BOUNCE BLOCKLIST -----------------------------------------------------
const blocked = new Set();
try {
  for (const r of $('Read BOUNCES').all().map(i => i.json)) {
    if (String(r.hard_or_soft || '').trim().toUpperCase() !== 'HARD') continue;
    const a = String(r.bounced_address || '').trim().toLowerCase();
    if (a) blocked.add(a);
  }
} catch (e) { /* BOUNCES not wired yet - fail open rather than stop the run */ }

const GENERIC = new Set(['gmail.com','yahoo.com','outlook.com','hotmail.com','icloud.com','live.com','protonmail.com','rediffmail.com','yahoo.co.in','me.com','aol.com']);
const bookEmails = new Set(); const bookDomains = new Set(); const bookNames = new Set();
const normName = s => String(s || '').toLowerCase().replace(/[^a-z ]/g, ' ').replace(/\s+/g, ' ').trim();
for (const r of inv) {
  for (const part of String(r.contact_person || '').split(/[,;&]| and /i)) {
    const n = normName(part); if (n.split(' ').length >= 2) bookNames.add(n);
  }
  for (const f of ['email', 'cc']) {
    const m = String(r[f] || '').toLowerCase().match(/[\w.+-]+@[\w-]+\.[\w.-]+/g) || [];
    for (const e of m) { bookEmails.add(e); const d = e.split('@')[1]; if (!GENERIC.has(d)) bookDomains.add(d); }
  }
}

const remaining = {};
for (const m of ACTIVE) remaining[m.id] = m.cap;
let sentTodayTotal = 0;
for (const r of onb) {
  if (!isToday(r.sent_date)) continue;
  sentTodayTotal++;
  const m = mbFor(String(r.email || '').trim().toLowerCase());
  if (m) remaining[m.id] = Math.max(0, remaining[m.id] - 1);
}
const used = new Set(onb.filter(r => String(r.sent_date || '').trim()).map(r => String(r.email || '').trim().toLowerCase()));

const EM = /^[^@\s;,]+@[^@\s;,]+\.[a-z]{2,}$/i;
const rank = r => Number(r.send_order) || (1e6 + Number(r.rank)) || 1e9;
const cand = onb
  .filter(r => String(r.status || '').trim().toUpperCase() === 'QUEUED' && !String(r.sent_date || '').trim())
  .sort((a, b) => rank(a) - rank(b));

const out = []; const perMb = {}; let blockedHits = 0;
for (const r of cand) {
  if (!Object.values(remaining).some(v => v > 0)) break;
  const email = String(r.email || '').trim().toLowerCase();
  const dom = email.split('@')[1] || '';
  if (!EM.test(email)) continue;
  if (blocked.has(email)) { blockedHits++; continue; }
  const cs = String(r.contact_status || '').trim().toUpperCase();
  if (cs === 'SITE_DEAD' || cs === 'BOUNCED') continue;
  if (bookEmails.has(email) || (dom && !GENERIC.has(dom) && bookDomains.has(dom))) continue;
  const cname = normName(r.contact);
  if (cname.split(' ').length >= 2 && bookNames.has(cname)) continue;
  if (used.has(email)) continue;
  const raw = String(r.body_html || '');
  if (!raw.includes('calendly.com/investors-sidanaventures/30min') || raw.includes('{{')) continue;
  if (!String(r.subject || '').trim()) continue;
  const m = mbFor(email);
  if (!m || remaining[m.id] <= 0) continue;
  const html = finalise(raw, m.signature, m.name);
  if (!html.toLowerCase().includes(SIG_MARK)) continue;
  out.push({ json: { rank: String(r.rank), firm: r.firm, to: email, subject: r.subject, html, mb: m.id, senderName: m.name } });
  used.add(email); remaining[m.id]--; perMb[m.id] = (perMb[m.id] || 0) + 1;
}
if (!out.length) return [];
out[0].json._plan = { totalPicked: out.length, perMailbox: perMb, alreadySentToday: sentTodayTotal,
  blocklistSize: blocked.size, skippedAsBounced: blockedHits,
  capsInUse: ACTIVE.map(m => m.id + ':' + m.cap).join(' '), disabledMailboxes: disabled };
return out;

const src = $('Loop Over Sends').item.json;
return { json: {
  rank: src.rank,
  status: 'SENT',
  sent_date: new Date().toLocaleString('sv-SE', { timeZone: 'Asia/Kolkata' }),
  thread_id: $json.threadId || $json.id || ''
} };

const src = $('Loop Over Sends').item.json;
const err = $json.error ? ($json.error.message || JSON.stringify($json.error)) : 'unknown error';
return { json: {
  rank: src.rank,
  status: 'SEND_ERROR',
  notes: 'Send failed ' + new Date().toLocaleString('sv-SE', { timeZone: 'Asia/Kolkata' }) + ': ' + String(err).slice(0, 200)
} };

// $('Mark SENT').all() only returns the LAST loop run, so counting it under-reports (logged 1 of 10
// on 17 Sep). Count across every run index instead.
function countAll(node) {
  let total = 0;
  for (let i = 0; i < 200; i++) {
    try { const r = $(node).all(0, i); if (!r || !r.length) { if (i > 2) break; continue; } total += r.length; } catch (e) { break; }
  }
  return total;
}
const sent = countAll('Mark SENT');
const failed = countAll('Mark ERROR');
const skipped = countAll('Mark SKIPPED');
return [{ json: {
  date: new Date().toLocaleString('sv-SE', { timeZone: 'Asia/Kolkata' }),
  workflow: 'ONB-1 Onboarding Send (Shradhaa)',
  rows_read: $('Read ONBOARDING').all().length,
  decided: $('Pick today batch').all().length,
  sent: sent,
  skipped: skipped + failed,
  skip_reasons: [skipped ? skipped + ' skipped - prior contact found in a mailbox' : '', failed ? failed + ' send errors - see ONBOARDING status SEND_ERROR' : ''].filter(Boolean).join('; ')
} }];

// The INVESTORS book records who we decided to KEEP, not who we have SPOKEN to. Chanakya,
// Seafund and Avaana were each emailed cold while a live thread existed in a mailbox the
// book knew nothing about. So ask the mailboxes, one query per address/domain - grouped OR
// searches silently drop matches at Gmail's 50-result cap.
const src = $('Loop Over Sends').first().json;
const cnt = n => { try { return (($(n).first().json || {}).messages || []).length; } catch (e) { return 0; } };
const hits = { mb5: cnt('Check mb5 (Shradhaa)'), mb4: cnt('Check mb4 (Akansha)'), mb3: cnt('Check mb3 (investors)'), mb2: cnt('Check mb2 (dealflow)') };
const total = hits.mb5 + hits.mb4 + hits.mb3 + hits.mb2;
return [{ json: Object.assign({}, src, { prior_hits: hits, prior_total: total, skip: total > 0 }) }];

const h = $json.prior_hits || {};
return { json: {
  rank: String($json.rank),
  status: 'SKIPPED_PRIOR_CONTACT',
  review_note: 'Not sent ' + new Date().toLocaleString('sv-SE', { timeZone: 'Asia/Kolkata' }) + ': existing mail with this address/domain - Shradhaa ' + (h.mb5 || 0) + ', Akansha ' + (h.mb4 || 0) + ', investors ' + (h.mb3 || 0) + ', dealflow ' + (h.mb2 || 0) + '. Read the thread before any approach.'
} };

